:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --text-dim: #a0a0b0;
  --snake: #4ecca3;
  --food: #e94560;
  --border: #2a2a4a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.score-box {
  text-align: right;
}

.score-label {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.board-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  margin-bottom: 20px;
  border-radius: 12px;
  overflow: hidden;
  border: 2px solid var(--border);
  background: var(--accent);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  gap: 12px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  display: none;
}

.overlay h2 {
  font-size: 1.25rem;
  color: var(--primary);
}

.overlay p {
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--text-dim);
  max-width: 280px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid var(--border);
  border-radius: 10px;
  background: var(--accent);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  min-width: 120px;
}

.btn:hover {
  background: #1a4a7a;
  border-color: var(--primary);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: #0d2a4a;
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #ff5a75;
  border-color: #ff5a75;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}

.hint {
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-dim);
}

kbd {
  background: var(--accent);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: inherit;
  font-size: 0.8rem;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 100px;
    font-size: 0.9rem;
  }
  .controls {
    gap: 8px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 18;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  let snake, dir, nextDir, food, score, state, lastTick, rafId;

  function reset() {
    snake = [{ x: 9, y: 9 }, { x: 8, y: 9 }, { x: 7, y: 9 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    state = 'paused';
    lastTick = 0;
    placeFood();
    updatePauseBtn();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function updatePauseBtn() {
    pauseBtn.textContent = state === 'playing' ? 'Pause' : 'Resume';
    pauseBtn.setAttribute('aria-label', state === 'playing' ? 'Pause game' : 'Resume game');
  }

  function showOverlay(title, text, btnLabel, action) {
    overlayTitle.textContent = title;
    overlayText.textContent = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
    overlayBtn.onclick = action;
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function startGame() {
    reset();
    state = 'playing';
    updatePauseBtn();
    hideOverlay();
    lastTick = performance.now();
    if (!rafId) rafId = requestAnimationFrame(loop);
  }

  function togglePause() {
    if (state === 'playing') {
      state = 'paused';
      updatePauseBtn();
      showOverlay('Paused', 'Press Space or click Resume to continue.', 'Resume', togglePause);
    } else if (state === 'paused') {
      state = 'playing';
      updatePauseBtn();
      hideOverlay();
      lastTick = performance.now();
    }
  }

  function gameOver() {
    state = 'over';
    updatePauseBtn();
    showOverlay('Game Over', 'Your score: ' + score + '. Press Restart or R to play again.', 'Restart', startGame);
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      gameOver();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#6ff0c0' : '#4ecca3';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function loop(now) {
    rafId = requestAnimationFrame(loop);
    if (state === 'playing') {
      if (now - lastTick >= TICK_MS) {
        lastTick = now;
        step();
      }
    }
    draw();
  }

  function setDirection(x, y) {
    if (state !== 'playing') return;
    if (x === -dir.x && y === -dir.y) return;
    nextDir = { x, y };
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight') {
      e.preventDefault();
      if (key === 'ArrowUp') setDirection(0, -1);
      else if (key === 'ArrowDown') setDirection(0, 1);
      else if (key === 'ArrowLeft') setDirection(-1, 0);
      else if (key === 'ArrowRight') setDirection(1, 0);
    } else if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (state === 'playing' || state === 'paused') togglePause();
    } else if (key === 'r' || key === 'R') {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', () => {
    if (state === 'playing' || state === 'paused') togglePause();
  });

  restartBtn.addEventListener('click', startGame);

  reset();
  showOverlay(
    'How to Play',
    'Use the arrow keys to move the snake. Eat the red food to grow and score points. Avoid hitting the walls or yourself.',
    'Start Game',
    startGame
  );
  draw();
})();
